/** Restart warm profile of the same immutable joint field; no fallback reprepare. */
import{readFileSync,writeFileSync}from'node:fs';import{createHash}from'node:crypto';import{runAnalysisProblem,terminateAnalysisPool}from'../../../src/analyze/run-analysis.ts';import{localCoreIdentity}from'../../../src/analyze/local-model-cache.ts';
const source=process.argv[2],out=process.env.P7_OUTPUT_DIR!;process.env.PCB_ANALYSIS_CACHE_DIR=source+'/cache';process.env.P7_VERIFY_MEMORY_MIB='1024';const identity=JSON.parse(readFileSync(source+'/identity.json','utf8')),old=JSON.parse(readFileSync(source+'/joint-warm.json','utf8')),boardJson=readFileSync('tests/fixtures/analysis-p7-joint-section/'+identity.variant+'.json','utf8');if(identity.core!==localCoreIdentity()||identity.boardSha256!==createHash('sha256').update(boardJson).digest('hex'))throw Error('WARM_PHYSICAL_CORE_IDENTITY');const entry=JSON.parse(readFileSync(source+'/cache/'+old.cache.key+'.json','utf8'));if(createHash('sha256').update(entry.payload).digest('hex')!==entry.checksum)throw Error('WARM_CHECKSUM');
try{const started=performance.now(),r=await runAnalysisProblem({kind:'local-extraction',request:{boardJson,geometry:identity.geometry,magneticPatchLevel:2,remainingSeconds:30,frequenciesHz:identity.frequencies,bandHz:[1000,100000],observablesOnly:true,drive:[1,0,-1,0],loadsOhm:[50,50,50,50]}},{timeoutMs:35000});if(r.cache.assembly!==0||r.cache.training!==0)throw Error('WARM_REASSEMBLED');writeFileSync(out+'/warm-profile.json',JSON.stringify({wallSeconds:(performance.now()-started)/1000,cache:r.cache,source,resources:r.resources,stageCounts:r.stageCounts}));writeFileSync(out+'/comparison.json',JSON.stringify({status:'unsupported',scope:'warm cache verified, no D1 physical admission'}));}finally{await terminateAnalysisPool();}
